package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.copyCurrentStructure
 */
public class TokenBuffer_copyCurrentStructure_TriageGen1Test {

    private ObjectMapper mapper;
    private JsonFactory factory;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        factory = mapper.getFactory();
    }

    private String getBufferContent(TokenBuffer buffer) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try (JsonGenerator gen = factory.createGenerator(out)) {
            buffer.serialize(gen);
        }
        return out.toString();
    }

    @Test
    public void testCopySimpleValue() throws IOException {
        String json = "\"test\"";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to START_STRING
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("\"test\"", getBufferContent(buffer));
    }

    @Test
    public void testCopyNumber() throws IOException {
        String json = "123";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken();
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("123", getBufferContent(buffer));
    }

    @Test
    public void testCopyBoolean() throws IOException {
        String json = "true";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken();
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("true", getBufferContent(buffer));
    }

    @Test
    public void testCopyNull() throws IOException {
        String json = "null";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken();
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("null", getBufferContent(buffer));
    }

    @Test
    public void testCopyArray() throws IOException {
        String json = "[1, \"two\", {\"three\": 3}]";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_ARRAY
            buffer.copyCurrentStructure(jp);
        }
        // Note: serialize might add whitespace depending on config, but standard is compact
        assertEquals("[1,\"two\",{\"three\":3}]", getBufferContent(buffer));
    }

    @Test
    public void testCopyObject() throws IOException {
        String json = "{\"key\":\"value\", \"num\":123}";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("{\"key\":\"value\",\"num\":123}", getBufferContent(buffer));
    }

    @Test
    public void testCopyFieldAndValue() throws IOException {
        // This tests the 'if (t == JsonToken.FIELD_NAME)' branch
        String json = "{\"field\":\"value\"}";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME "field"
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("{\"field\":\"value\"}", getBufferContent(buffer));
    }

    @Test
    public void testCopyNestedStructures() throws IOException {
        String json = "{\"outer\": [{\"inner\": \"val\"}]}";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME "outer"
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("{\"outer\":[{\"inner\":\"val\"}]}", getBufferContent(buffer));
    }

    @Test
    public void testWithNativeIdsEnabled() throws IOException {
        // Testing the _mayHaveNativeIds logic branches
        // We use the constructor that sets hasNativeIds to true
        TokenBuffer buffer = new TokenBuffer(mapper, true);
        String json = "{\"id\": 1}";
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME "id"
            buffer.copyCurrentStructure(jp);
        }
        // The output should contain the structure. 
        // Since we aren't actually providing ObjectIds in the parser, 
        // it just exercises the _checkNativeIds calls.
        assertEquals("{\"id\":1}", getBufferContent(buffer));
    }

    @Test
    public void testEmptyObject() throws IOException {
        String json = "{}";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken();
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("{}", getBufferContent(buffer));
    }

    @Test
    public void testEmptyArray() throws IOException {
        String json = "[]";
        TokenBuffer buffer = new TokenBuffer(mapper);
        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken();
            buffer.copyCurrentStructure(jp);
        }
        assertEquals("[]", getBufferContent(buffer));
    }
}
